import Link from "next/link";

export default function HeroSection() {
  return (
    <section
      style={{
        minHeight: "100vh",
        padding: "120px 48px 80px",
        display: "grid",
        gridTemplateColumns: "1fr 1fr",
        gap: 48,
        alignItems: "center",
        position: "relative",
        overflow: "hidden",
      }}
    >
      <div>
        <div
          style={{
            fontFamily: "'DM Mono', monospace",
            fontSize: 11,
            letterSpacing: ".14em",
            color: "var(--text-3)",
            textTransform: "uppercase",
            marginBottom: 20,
            display: "flex",
            alignItems: "center",
            gap: 8,
          }}
        >
          ✦ design it yourself
        </div>
        <h1
          style={{
            fontFamily: "'Cormorant Garamond', serif",
            fontSize: 68,
            fontWeight: 300,
            lineHeight: 1.08,
            letterSpacing: "-.01em",
            marginBottom: 24,
            opacity: 0,
            animation: "fadeUp .8s ease forwards .1s",
          }}
        >
          Some gifts
          <br />
          are bought.
          <br />
          This one is{" "}
          <em style={{ fontStyle: "italic", color: "var(--brown)" }}>made.</em>
        </h1>
        <p
          style={{
            fontSize: 17,
            fontWeight: 300,
            color: "var(--text-2)",
            lineHeight: 1.75,
            maxWidth: 420,
            marginBottom: 36,
            opacity: 0,
            animation: "fadeUp .8s ease forwards .3s",
          }}
        >
          Design your own Polaroid. Add a caption only you would write, a song
          only you two know. Then hold it in your hands — or send it to theirs.
        </p>
        <div
          style={{
            display: "flex",
            gap: 12,
            alignItems: "center",
            opacity: 0,
            animation: "fadeUp .8s ease forwards .45s",
          }}
        >
          <Link
            href="/editor"
            style={{
              fontFamily: "'DM Sans', sans-serif",
              fontSize: 15,
              fontWeight: 500,
              background: "var(--brown)",
              color: "#fff",
              border: "none",
              borderRadius: 100,
              padding: "14px 32px",
              cursor: "pointer",
              transition: "all .22s ease",
              textDecoration: "none",
              display: "inline-block",
            }}
          >
            Make Your First Polaroid →
          </Link>
          <button
            style={{
              fontFamily: "'DM Sans', sans-serif",
              fontSize: 14,
              fontWeight: 400,
              color: "var(--text-2)",
              background: "transparent",
              border: "none",
              cursor: "pointer",
              textDecoration: "underline",
              textUnderlineOffset: 3,
            }}
            onClick={() =>
              document
                .getElementById("templates")
                ?.scrollIntoView({ behavior: "smooth" })
            }
          >
            See templates
          </button>
        </div>
      </div>

      {/* Floating polaroids */}
      <div
        className="hero-visual"
        style={{
          position: "relative",
          height: 520,
          opacity: 0,
          animation: "fadeIn .9s ease forwards .5s",
        }}
      >
        {/* P1 */}
        <div
          style={{
            position: "absolute",
            background: "#fff",
            boxShadow: "0 12px 40px rgba(0,0,0,.12)",
            borderRadius: 3,
            width: 160,
            top: 20,
            left: 40,
            transform: "rotate(-4deg)",
            animation: "float1 6s ease-in-out infinite",
            transition: "transform .3s ease",
          }}
        >
          <div
            style={{
              height: 138,
              margin: "10px 10px 0",
              background: "linear-gradient(135deg, #e8d5c0, #c4a882)",
              overflow: "hidden",
            }}
          />
          <div
            style={{
              height: 42,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
            }}
          >
            <span
              style={{
                fontFamily: "'Dancing Script', cursive",
                fontSize: 15,
                color: "#5a4a3a",
              }}
            >
              always you
            </span>
          </div>
        </div>

        {/* P2 */}
        <div
          style={{
            position: "absolute",
            background: "#fff",
            boxShadow: "0 12px 40px rgba(0,0,0,.12)",
            borderRadius: 3,
            width: 155,
            top: 60,
            left: 200,
            transform: "rotate(3deg)",
            animation: "float2 7s ease-in-out infinite .8s",
            transition: "transform .3s ease",
          }}
        >
          <div
            style={{
              height: 132,
              margin: "9px 9px 0",
              background: "linear-gradient(135deg, #d4c5b0, #a89080)",
            }}
          />
          <div
            style={{
              height: 36,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
            }}
          >
            <span
              style={{
                fontFamily: "'DM Mono', monospace",
                fontSize: 10,
                color: "#7a6e65",
                letterSpacing: ".08em",
              }}
            >
              26 · 04 · 2025
            </span>
          </div>
        </div>

        {/* P3 — Spotify */}
        <div
          style={{
            position: "absolute",
            background: "#fff",
            boxShadow: "0 12px 40px rgba(0,0,0,.12)",
            borderRadius: 3,
            width: 175,
            top: 220,
            left: 80,
            transform: "rotate(-2deg)",
            animation: "float3 5.5s ease-in-out infinite 1.2s",
            transition: "transform .3s ease",
          }}
        >
          <div
            style={{
              height: 152,
              margin: "10px 10px 0",
              background: "linear-gradient(160deg, #c8b8a0, #8b7060)",
            }}
          />
          <div
            style={{
              height: 38,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              gap: 6,
            }}
          >
            <div
              style={{
                width: 20,
                height: 20,
                background: "#1a1714",
                borderRadius: "50%",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
              }}
            >
              <svg width="12" height="12" viewBox="0 0 24 24" fill="white">
                <path d="M12 0C5.4 0 0 5.4 0 12s5.4 12 12 12 12-5.4 12-12S18.66 0 12 0zm5.521 17.34c-.24.359-.66.48-1.021.24-2.82-1.74-6.36-2.101-10.561-1.141-.418.122-.779-.179-.899-.539-.12-.421.18-.78.54-.9 4.56-1.021 8.52-.6 11.64 1.32.42.18.479.659.301 1.02zm1.44-3.3c-.301.42-.841.6-1.262.3-3.239-1.98-8.159-2.58-11.939-1.38-.479.12-1.02-.12-1.14-.6-.12-.48.12-1.021.6-1.141C9.6 9.9 15 10.561 18.72 12.84c.361.181.54.78.241 1.2zm.12-3.36C15.24 8.4 8.82 8.16 5.16 9.301c-.6.179-1.2-.181-1.38-.721-.18-.601.18-1.2.72-1.381 4.26-1.26 11.28-1.02 15.721 1.621.539.3.719 1.02.419 1.56-.299.421-1.02.599-1.559.3z" />
              </svg>
            </div>
            <div style={{ display: "flex", gap: 1.5, alignItems: "center" }}>
              {Array.from({ length: 18 }, (_, i) => (
                <div
                  key={i}
                  style={{
                    width: 2.5,
                    background: "#1a1714",
                    borderRadius: 1,
                    height: 6 + Math.sin(i * 0.8) * 5,
                  }}
                />
              ))}
            </div>
          </div>
        </div>

        {/* P4 — Tape */}
        <div
          style={{
            position: "absolute",
            background: "#fff",
            boxShadow: "0 12px 40px rgba(0,0,0,.12)",
            borderRadius: 3,
            width: 148,
            top: 30,
            left: 360,
            transform: "rotate(5deg)",
            animation: "float4 8s ease-in-out infinite .4s",
            transition: "transform .3s ease",
          }}
        >
          <div
            style={{
              position: "absolute",
              top: -8,
              left: "50%",
              transform: "translateX(-50%) rotate(-2deg)",
              width: 55,
              height: 16,
              background: "rgba(255,210,100,.55)",
              borderRadius: 2,
              zIndex: 2,
            }}
          />
          <div
            style={{
              height: 125,
              margin: "9px 9px 0",
              background: "linear-gradient(135deg, #e0ceb8, #b89878)",
            }}
          />
          <div
            style={{
              height: 34,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
            }}
          >
            <span
              style={{
                fontFamily: "'Dancing Script', cursive",
                fontSize: 13,
                color: "#7a6e65",
              }}
            >
              besties forever
            </span>
          </div>
        </div>
      </div>

      <style jsx>{`
        @media (max-width: 768px) {
          section {
            grid-template-columns: 1fr !important;
            padding: 100px 24px 60px !important;
            gap: 40px !important;
          }
          h1 { font-size: 44px !important; }
          .hero-visual { height: 320px !important; }
        }
      `}</style>
    </section>
  );
}
